        vm.deal(address(c), 0); // ensure clean state
        uint256 before = c.depositsCount();
        // Send ETH to the contract via sendMoney, which may fail but still triggers fallback?
        // Actually, sendMoney sends ETH to target, not to self. To affect depositsCount, we need a call that sends ETH to the contract.
