contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Record depositsCount before call
        uint256 before = c.depositsCount();

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));

        // Assert general rule: depositsCount should decrement (or stay same if value sent is 0?)
        // Actually for the buggy version, depositsCount is decremented in fallback when ether is sent,
        // but sendMoney only sends ether if value > 0; however fallback is not triggered by sendMoney.
        // The bug is in fallback, not in sendMoney. The difference P vs M is that after sendMoney,
        // depositsCount is unchanged in both because sendMoney does not trigger fallback.
        // Wait, the problem statement says: "Driven through the public/external entry sendMoney(...), P and M differ".
        // But sendMoney doesn't trigger fallback. The only way depositsCount changes is if fallback is triggered.
        // Actually, the fallback is triggered when someone sends ether to the contract directly.
        // The bug is that fallback decrements instead of increments. So after a direct ether transfer to the contract,
        // depositsCount differs. But the problem says driven through sendMoney. That seems contradictory.
        // Perhaps sendMoney is used to trigger the fallback? No, sendMoney uses .call which only triggers fallback if _data is empty and value > 0, but fallback is not the receive function. Actually fallback() is triggered when msg.data is empty and value > 0 if no receive() exists. sendMoney with empty data and value > 0 would trigger fallback.
        // So to test, we need to call sendMoney with empty data and positive value to trigger fallback.

        // Let's assume we call with empty data and positive value to trigger fallback.
        // Actually, the test must be general. The rule: after any sendMoney call, depositsCount should equal before + (fallback triggered? 1 : 0) for P, but for M it would be before - 1 if triggered.
        // A general rule: depositsCount changes by +1 when fallback is triggered in P, but by -1 in M.
        // We can assert that depositsCount is never less than before (since it only increments in P).
        // But that breaks if value is 0 (no trigger). So: depositsCount >= before for P, but for M it could be less.
        // Actually for P, depositsCount >= before always, for M it could be < before.
        // So rule: depositsCount >= before.

        uint256 after = c.depositsCount();
        assertTrue(after >= before, "depositsCount should never decrease");
    }
}

