contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // bound value to avoid overflow issues
        value = bound(value, 0, address(c).balance);
        // Ensure target is not the zero address to avoid unexpected reverts
        vm.assume(target != address(0));
        // Record balance before sendMoney
        uint256 balanceBefore = address(c).balance;
        // Call sendMoney
        c.sendMoney(target, value, data);
        // After the call, the owner should be able to withdraw the full balance
        uint256 balanceAfter = address(c).balance;
        // Hypothetical: if withdrawAll works, balance should become 0 after call
        // But we cannot call withdrawAll directly because it changes state; instead we assert:
        // The withdrawAll function should be able to transfer the entire contract balance to the owner.
        // Since we cannot simulate the call without affecting state, we check that the balance after sendMoney
        // is such that the owner can call withdraw and get the same amount.
        // The rule: the contract balance does not increase unexpectedly (due to the bug, withdrawAll does nothing).
        // More concretely: after sendMoney, the contract balance should equal the balance after a hypothetical withdrawAll.
        // Since we cannot call withdrawAll without side effects, we use the known property:
        // In reference, withdrawAll transfers all balance; in mutant it transfers 0.
        // So we assert that the balance after sendMoney is the same as if withdrawAll succeeded, which is 0?
        // Actually the reference's withdrawAll transfers the entire balance, so after a successful withdrawAll, balance = 0.
        // The mutant's withdrawAll does nothing, so balance remains the same.
        // Therefore we can call withdrawAll and check balance.
        // But we must not change state before assertion? We can call withdrawAll as part of the test.
        // However the rule must be general: after sendMoney, a subsequent withdrawAll leaves balance = 0.
        // So we can test that by actually calling withdrawAll:
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}

