        uint256 balanceBefore = address(c).balance;
        uint256 safeValue = bound(value, 0, address(c).balance);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, safeValue, data));
        if (success) {
            assertTrue(address(c).balance == balanceBefore - safeValue);
        } else {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

